-- Peserta per event (Event Management, module Event).
-- Aturan: tabel baru pakai awalan T_. Satu baris = satu tiket.
-- Terjual DIHITUNG dari baris aktif (tanpa kolom jumlah).
-- ORDERID/ORDERCODE disiapkan NULL untuk dipakai ulang module Ticketing nanti.
-- Kode tiket acak non-urutan (dari NEWID). Data contoh fiktif jelas palsu.
-- Idempoten: CREATE/index hanya bila belum ada; seed per EMAIL (unik).
-- Jalankan per pernyataan (pisahkan tiap GO).
-- ROLLBACK (jalankan manual bila perlu): DROP TABLE dbo.T_ATTENDEE;

IF OBJECT_ID('dbo.T_ATTENDEE', 'U') IS NULL
CREATE TABLE dbo.T_ATTENDEE (
    ATTENDEEID INT IDENTITY(1,1) NOT NULL PRIMARY KEY,
    EVENTID INT NOT NULL,
    TICKETTYPEID INT NOT NULL,
    NAME VARCHAR(100) NOT NULL,
    EMAIL VARCHAR(100) NULL,
    PHONE VARCHAR(30) NULL,
    TICKETCODE VARCHAR(30) NOT NULL,
    SOURCE VARCHAR(10) NOT NULL DEFAULT 'MANUAL',
    PAYSTATUS VARCHAR(12) NOT NULL DEFAULT 'BELUM_BAYAR',
    ATTENDSTATUS VARCHAR(12) NOT NULL DEFAULT 'BELUM_HADIR',
    CHECKINTIME DATETIME2 NULL,
    TIKETSTATUS VARCHAR(10) NOT NULL DEFAULT 'AKTIF',
    ORDERID INT NULL,
    ORDERCODE VARCHAR(30) NULL,
    REGDATE DATETIME2 NOT NULL DEFAULT GETDATE(),
    SYSCREATEUSER VARCHAR(25) NULL,
    SYSCREATEDATE DATETIME2 NULL,
    SYSUPDATEUSER VARCHAR(25) NULL,
    SYSUPDATEDATE DATETIME2 NULL
);
GO

IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = 'UX_T_ATTENDEE_CODE' AND object_id = OBJECT_ID('dbo.T_ATTENDEE'))
CREATE UNIQUE INDEX UX_T_ATTENDEE_CODE ON dbo.T_ATTENDEE (TICKETCODE);
GO

IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = 'IX_T_ATTENDEE_EVENT' AND object_id = OBJECT_ID('dbo.T_ATTENDEE'))
CREATE INDEX IX_T_ATTENDEE_EVENT ON dbo.T_ATTENDEE (EVENTID, TIKETSTATUS);
GO

IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = 'IX_T_ATTENDEE_TYPE' AND object_id = OBJECT_ID('dbo.T_ATTENDEE'))
CREATE INDEX IX_T_ATTENDEE_TYPE ON dbo.T_ATTENDEE (TICKETTYPEID, TIKETSTATUS);
GO

IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = 'IX_T_ATTENDEE_CODE' AND object_id = OBJECT_ID('dbo.T_ATTENDEE'))
CREATE INDEX IX_T_ATTENDEE_CODE ON dbo.T_ATTENDEE (TICKETCODE);
GO

IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = 'IX_T_ATTENDEE_STATUS' AND object_id = OBJECT_ID('dbo.T_ATTENDEE'))
CREATE INDEX IX_T_ATTENDEE_STATUS ON dbo.T_ATTENDEE (EVENTID, PAYSTATUS, ATTENDSTATUS);
GO

-- Data contoh fiktif (40 baris, campuran status). Pola tiap baris:
-- INSERT ... SELECT <event>, T.TICKETTYPEID, ... FROM T_TICKET_TYPE T WHERE ...
-- + WHERE NOT EXISTS (EMAIL) supaya idempoten walau ID berubah.

-- Event 2 (Festival Kuliner Bandung)
INSERT INTO dbo.T_ATTENDEE (EVENTID, TICKETTYPEID, NAME, EMAIL, PHONE, TICKETCODE, SOURCE, PAYSTATUS, ATTENDSTATUS, TIKETSTATUS, SYSCREATEUSER, SYSCREATEDATE)
SELECT 2, T.TICKETTYPEID, 'Peserta Uji 01', 'peserta01@contoh.test', '0812000001', 'T-' + UPPER(SUBSTRING(REPLACE(CAST(NEWID() AS VARCHAR(36)), '-', ''), 1, 10)), 'MANUAL', 'LUNAS', 'BELUM_HADIR', 'AKTIF', 'SEED', GETDATE() FROM dbo.T_TICKET_TYPE T WHERE T.EVENTID = 2 AND T.NAME = 'Regular' AND NOT EXISTS (SELECT 1 FROM dbo.T_ATTENDEE WHERE EMAIL = 'peserta01@contoh.test');
GO

